pub fn min_gap(values: &[i64]) -> i64 {
    let mut best = i64::MAX;
    for i in 0..values.len() {
        for j in 0..values.len() {
            if i != j {
                let gap = (values[i] - values[j]).abs();
                if gap < best {
                    best = gap;
                }
            }
        }
    }
    best
}

